node -e "
const fs = require('fs');
const path = require('path');
const root = 'c:/Users/adiwi/OneDrive/Documents/Personal/Code/CodingCamp-24August26-MRizkiAdiwiganda';

const js  = fs.readFileSync(path.join(root,'js','app.js'),'utf8');
const css = fs.readFileSync(path.join(root,'css','styles.css'),'utf8');
const html= fs.readFileSync(path.join(root,'index.html'),'utf8');

const errors = [];

// Every getElementById in JS must have a matching id in HTML (except toast which is dynamic)
const jsIds   = [...js.matchAll(/getElementById\('([^']+)'\)/g)].map(m=>m[1]).filter(id=>id!=='toast');
const htmlIds = [...html.matchAll(/id=\"([^\"]+)\"/g)].map(m=>m[1]);
const missingIds = jsIds.filter(id => !htmlIds.includes(id));
if (missingIds.length) errors.push('FAIL ids used in JS but missing from HTML: ' + missingIds.join(', '));

// Key JS-generated class names must exist in CSS
const requiredClasses = [
  'todo-item','todo-checkbox','todo-task-text','todo-item-actions',
  'priority-badge','priority-high','priority-medium','priority-low',
  'priority-item-high','priority-item-medium','priority-item-low',
  'link-item','link-icon','link-name','link-overlay',
  'btn-action','intro-word','intro-word--visible',
  'intro-name-input','intro-name-input--shake','dashboard-visible'
];
requiredClasses.forEach(cls => {
  if (!css.includes('.' + cls)) errors.push('FAIL .' + cls + ' missing from css/styles.css');
});

if (errors.length) { console.error(errors.join('\n')); process.exit(1); }
else { console.log('OK — all IDs and class names are consistent'); }
"
